function mergeBaseEquipment(list){const current=(Array.isArray(list)?list:[]).map(e=>({...e,name:e.name||e.model||"Eigenes Gerät",category:e.category||"Sonstiges Zubehör",settings:Array.isArray(e.settings)?e.settings:[]})),ids=new Set(current.map(e=>e.id));return [...current,...baseEquipment.filter(e=>!ids.has(e.id)).map(e=>({...e,settings:[]}))]}
