function deepFreeze(value){if(value&&typeof value==="object"&&!Object.isFrozen(value)){Object.freeze(value);Object.values(value).forEach(deepFreeze)}return value}
function freezeHistory(sessions){sessions.forEach(deepFreeze);return sessions}
function normalizeState(x){
 if(!x||!Array.isArray(x.profiles)||!x.profiles.length)throw Error("Keine Profile vorhanden");
 const legacyExercises=Array.isArray(x.exercises)?x.exercises:baseExercises;
 x.profiles=x.profiles.map((p,i)=>({id:String(p.id||`p${i+1}`),name:String(p.name||"Athlet"),goal:p.goal||"Muskelaufbau",level:p.level||"Fortgeschritten",weight:Number(p.weight)||0,startDate:p.startDate||new Date().toISOString().slice(0,10),activePlan:p.activePlan||"",plans:Array.isArray(p.plans)?p.plans:[],sessions:freezeHistory(Array.isArray(p.sessions)?p.sessions:[]),equipment:mergeBaseEquipment(p.equipment),weights:Array.isArray(p.weights)?p.weights:[],exercises:(Array.isArray(p.exercises)?p.exercises:legacyExercises).map(e=>({...e})).concat(baseExercises.filter(e=>!(Array.isArray(p.exercises)?p.exercises:legacyExercises).some(existing=>existing.id===e.id)).map(e=>({...e}))),activeSession:p.activeSession&&typeof p.activeSession==="object"?{...p.activeSession,profileId:String(p.id||`p${i+1}`)}:null}));
 if(!x.profiles.some(p=>p.id===x.activeProfile))x.activeProfile=x.profiles[0].id;
 x.version=2;x.design=x.design||{accent:"#f4d21f",radius:16,button:1,title:"Bereit für Arbeit."};
 // Keep the old call sites working while resolving the library from the active profile.
 delete x.exercises;Object.defineProperty(x,"exercises",{configurable:true,enumerable:false,get(){return this.profiles.find(p=>p.id===this.activeProfile)?.exercises||[]}});
 return x;
}
function load(){
 try{const current=JSON.parse(localStorage.getItem(KEY));if(current?.version===2)return normalizeState(current)}catch(e){console.warn("Gespeicherter Datenstand konnte nicht geladen werden",e)}
 try{const legacy=JSON.parse(localStorage.getItem(LEGACY_KEY));if(legacy&&Array.isArray(legacy.profiles)&&legacy.profiles.length){const migrated=normalizeState(legacy);try{const draft=JSON.parse(localStorage.getItem(DRAFT_KEY)),owner=migrated.profiles.find(p=>p.id===migrated.activeProfile);if(draft&&owner&&!owner.activeSession)owner.activeSession={...draft,profileId:owner.id}}catch{};try{const migratedJson=JSON.stringify(migrated);localStorage.setItem(KEY,migratedJson);if(localStorage.getItem(KEY)!==migratedJson)throw Error("Migration konnte nicht bestätigt werden")}catch(storageError){console.warn("Neue Datenstruktur konnte noch nicht gespeichert werden; Altdaten bleiben erhalten",storageError)}return migrated}}catch(e){console.warn("Migration der vorhandenen Daten ist fehlgeschlagen; Altdaten bleiben erhalten",e)}
 return normalizeState(defaultState())
}
function save(){state.savedAt=Date.now();const snapshot=JSON.parse(JSON.stringify(state)),serialized=JSON.stringify(snapshot);return persistIndexedDB(snapshot).then(()=>{try{localStorage.setItem(KEY,serialized)}catch(e){console.warn("Lokale Wiederherstellungskopie konnte nicht aktualisiert werden",e)}return true}).catch(e=>{try{localStorage.setItem(KEY,serialized)}catch(storageError){console.warn("Auch localStorage ist nicht verfügbar",storageError)}console.warn("IndexedDB-Speicherung fehlgeschlagen; localStorage wurde als Fallback verwendet",e);return false})}
function openDatabase(){return new Promise((resolve,reject)=>{if(!("indexedDB"in window)){reject(Error("IndexedDB ist nicht verfügbar"));return}const request=indexedDB.open("logbook-local",1);request.onupgradeneeded=()=>{if(!request.result.objectStoreNames.contains("state"))request.result.createObjectStore("state")};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error||Error("IndexedDB konnte nicht geöffnet werden"))})}
function persistIndexedDB(snapshot=state){return openDatabase().then(db=>new Promise((resolve,reject)=>{const tx=db.transaction("state","readwrite");tx.objectStore("state").put(JSON.parse(JSON.stringify(snapshot)),"app-data-v2");tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>{db.close();reject(tx.error||Error("IndexedDB-Transaktion fehlgeschlagen"))};tx.onabort=()=>{db.close();reject(tx.error||Error("IndexedDB-Transaktion abgebrochen"))}}))}
async function restoreIndexedDBIfNeeded(){let db;try{db=await openDatabase();const data=await new Promise((resolve,reject)=>{const req=db.transaction("state").objectStore("state").get("app-data-v2");req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});db.close();db=null;const local=(()=>{try{return JSON.parse(localStorage.getItem(KEY)||"null")}catch{return null}})();if(data&&Number(data.savedAt||0)>=Number(local?.savedAt||0)){state=normalizeState(data);localStorage.setItem(KEY,JSON.stringify(state));return}if(local){state=normalizeState(local);await persistIndexedDB();return}await persistIndexedDB()}catch(e){if(db)db.close();console.warn("IndexedDB nicht verfügbar; lokale Daten werden als Fallback verwendet",e)}}
function profile(){return state.profiles.find(p=>p.id===state.activeProfile)||state.profiles[0]}
function esc(s){return String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function toast(s){const el=$("#toast");el.textContent=s;el.style.display="block";setTimeout(()=>el.style.display="none",2200)}
function $(s){return document.querySelector(s)} function $$(s){return [...document.querySelectorAll(s)]}
function modal(title,html){$("#modalTitle").textContent=title;$("#modalBody").innerHTML=html;$("#modal").classList.add("open")}
function closeModal(){$("#modal").classList.remove("open")}
function go(page){$$(".page").forEach(x=>x.classList.toggle("active",x.id==="page-"+page));$$(".nav button").forEach(x=>x.classList.toggle("active",x.dataset.page===page||(page==="equipment"&&x.dataset.page==="profile")));if(page==="home")renderHome();if(page==="analysis")renderAnalysis();if(page==="training")renderTraining();if(page==="equipment")renderEquipment();if(page==="history")renderHistory();if(page==="profile")renderProfile()}
function plan(){return profile().plans.find(p=>p.id===profile().activePlan)}
function exByName(n){return state.exercises.find(e=>e.name===n)||{id:uid(),name:n,muscle:"Sonstiges",equipment:"",unilateral:false}}
function makePlan(name,days){return{id:uid(),name,days:days.map(d=>({id:uid(),name:d[0],exercises:d[1].map(n=>({id:uid(),exerciseId:exByName(n).id,sets:3,reps:"8–12",rest:120,rir:2}))}))}}
function renderAll(){applyDesign();renderHome();renderAnalysis();renderTraining();renderEquipment();renderHistory();renderProfile()}
function applyDesign(){const d=state.design;document.documentElement.style.setProperty("--accent",d.accent||"#f4d21f");document.documentElement.style.setProperty("--radius",(d.radius||16)+"px");document.documentElement.style.setProperty("--btn",d.button??1)}
function renderHome(){const p=profile(),pl=plan(),sessions=p.sessions||[];$("#greeting").textContent=p.name+", "+(state.design.title||"bereit für Arbeit.");$("#profileNameTop").textContent=p.name;$("#avatarTop").textContent=(p.name||"L").slice(0,1).toUpperCase();$("#totalSessions").textContent=sessions.length;const week=sessions.filter(s=>Date.now()-new Date(s.date).getTime()<7*864e5).length;$("#weekSessions").textContent=week;$("#activePlanName").textContent=pl?.name||"Kein Plan";$("#activePlanInfo").textContent=pl?pl.days.length+" Trainingseinheiten":"Lege einen Plan an, um loszulegen.";$("#weightHome").textContent=p.weight?Number(p.weight).toFixed(1):"—";const last=sessions.slice().sort((a,b)=>b.date.localeCompare(a.date))[0];$("#lastSessionName").textContent=last?.dayName||"Noch keine Einheit";$("#lastSessionDate").textContent=last?new Date(last.date).toLocaleString("de-AT"):"Dein Verlauf erscheint hier.";$("#lastSessionVolume").textContent=last?Math.round(last.volume||0).toLocaleString("de-AT")+" kg Volumen":"";
const sel=$("#nextWorkoutSelect");sel.innerHTML=pl?pl.days.map(d=>`<option value="${d.id}">${esc(d.name)}</option>`).join(""):'<option value="">Kein aktiver Trainingsplan</option>';$("#nextWorkoutName").textContent=pl?.days[0]?.name||"Noch kein Plan";$("#nextWorkoutMeta").textContent=pl?pl.name+" · "+pl.days.length+" Einheiten":"Wähle einen Trainingsplan";sel.onchange=()=>{$("#nextWorkoutName").textContent=pl.days.find(d=>d.id===sel.value)?.name||""};$("#recentHome").innerHTML=sessions.length?sessions.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,3).map(s=>`<div class="item row between"><div><div class="item-title">${esc(s.dayName)}</div><div class="small">${new Date(s.date).toLocaleDateString("de-AT")} · ${s.exercises.length} Übungen</div></div><b>${Math.round(s.volume||0).toLocaleString("de-AT")} kg</b></div>`).join(""):'<div class="muted small">Noch keine Trainings gespeichert.</div>'}
function renderTraining(){const p=profile();$("#plansList").innerHTML=p.plans.length?p.plans.map(pl=>`<div class="item"><div class="row between wrap"><div><div class="item-title">${esc(pl.name)} ${pl.id===p.activePlan?'<span class="tag">AKTIV</span>':''}</div><div class="small">${pl.days.length} Einheiten · ${pl.days.map(d=>esc(d.name)).join(" / ")}</div></div><div class="actions"><button class="btn secondary" data-plan-edit="${pl.id}">Bearbeiten</button>${pl.id!==p.activePlan?`<button class="btn" data-plan-active="${pl.id}">Aktivieren</button>`:""}</div></div></div>`).join(""):'<p class="muted small">Noch kein Trainingsplan. Füge eine Vorlage hinzu.</p>';
$("#templateSelect").innerHTML=Object.keys(templates).map(n=>`<option>${esc(n)}</option>`).join("");renderExerciseList();renderSession();$$("[data-plan-active]").forEach(b=>b.onclick=()=>{p.activePlan=b.dataset.planActive;save();renderAll();toast("Trainingsplan aktiviert")});$$("[data-plan-edit]").forEach(b=>b.onclick=()=>editPlan(b.dataset.planEdit))}
function renderExerciseList(){const q=($("#exerciseSearch")?.value||"").toLowerCase();$("#muscleFilters").innerHTML=muscles.map(m=>`<button class="${selectedMuscle===m?'selected':''}" data-muscle="${esc(m)}">${esc(m)}</button>`).join("");$$("[data-muscle]").forEach(b=>b.onclick=()=>{selectedMuscle=b.dataset.muscle;renderExerciseList()});const list=state.exercises.filter(e=>(selectedMuscle==="Alle"||e.muscle===selectedMuscle)&&e.name.toLowerCase().includes(q));$("#exerciseList").innerHTML=list.map(e=>`<div class="item row between"><div><div class="item-title">${esc(e.name)}</div><div class="small">${esc(e.muscle)} · ${esc(e.equipment||"frei")}${e.unilateral?" · einseitig":""}</div></div><button class="btn ghost" data-ex-edit="${e.id}">Bearbeiten</button></div>`).join("")||'<p class="small muted">Keine Übungen gefunden.</p>';$$("[data-ex-edit]").forEach(b=>b.onclick=()=>editExercise(b.dataset.exEdit))}
function renderSession(){const on=!!activeSession;$("#sessionEmpty").classList.toggle("hidden",on);$("#sessionActive").classList.toggle("hidden",!on);if(!on)return;$("#sessionTitle").textContent=activeSession.dayName;$("#sessionStarted").textContent="Gestartet: "+new Date(activeSession.date).toLocaleTimeString("de-AT",{hour:"2-digit",minute:"2-digit"});const done=activeSession.exercises.reduce((a,e)=>a+e.sets.filter(s=>s.done).length,0);$("#sessionProgress").textContent=done+" Sätze protokolliert";$("#sessionExercises").innerHTML=activeSession.exercises.map((e,idx)=>renderExerciseSession(e,idx)).join("");wireSession()}
function lastExerciseValues(exId){const sessions=profile().sessions.slice().sort((a,b)=>b.date.localeCompare(a.date));for(const s of sessions){const e=s.exercises.find(x=>x.exerciseId===exId);if(e)return e.sets||[]}return[]}
function renderExerciseSession(e,idx){const def=state.exercises.find(x=>x.id===e.exerciseId)||{name:e.name,muscle:"",equipment:"",unilateral:false};const prev=lastExerciseValues(e.exerciseId);const prevText=prev.length?prev.map((s,i)=>`${s.weight||0} kg × ${s.reps||0}`).join(" · "):"Noch keine Vorwerte";return `<div class="card exercise-card"><div class="exercise-head"><div><div class="item-title">${esc(e.name||def.name)}</div><div class="small">${esc(e.muscle||def.muscle)} · ${esc(e.equipment||def.equipment||"")}${e.machineSettings?.length?" · "+esc(e.machineSettings.map(q=>q.label+": "+q.value).join(" · ")):""}</div><div class="small" style="margin-top:6px"><span class="tag">LETZTES MAL</span> ${esc(prevText)}</div></div><button class="btn ghost" data-remove-ex="${idx}">✕</button></div><table class="sets"><thead><tr><th>#</th><th>kg</th><th>Wdh.</th><th>RIR</th><th>Typ</th><th>✓</th></tr></thead><tbody>${e.sets.map((s,si)=>`<tr><td>${si+1}</td><td>${(e.unilateral??def.unilateral)?`<span class="side-label">L</span>`:""}<input type="number" step=".5" data-set="${idx},${si}" data-key="weight" value="${esc(s.weight)}" placeholder="kg"></td><td><input type="number" data-set="${idx},${si}" data-key="reps" value="${esc(s.reps)}" placeholder="Wdh."></td><td><input type="number" data-set="${idx},${si}" data-key="rir" value="${esc(s.rir)}" placeholder="2"></td><td><select data-set="${idx},${si}" data-key="type"><option ${s.type==="Arbeit"?"selected":""}>Arbeit</option><option ${s.type==="Aufwärmen"?"selected":""}>Aufwärmen</option><option ${s.type==="Dropset"?"selected":""}>Dropset</option><option ${s.type==="Back-off"?"selected":""}>Back-off</option></select></td><td><input type="checkbox" data-set="${idx},${si}" data-key="done" ${s.done?"checked":""}></td></tr>${(e.unilateral??def.unilateral)?`<tr><td></td><td><span class="side-label">R</span><input type="number" step=".5" data-set="${idx},${si}" data-key="weightR" value="${esc(s.weightR??s.weight)}" placeholder="kg"></td><td><input type="number" data-set="${idx},${si}" data-key="repsR" value="${esc(s.repsR??s.reps)}" placeholder="Wdh."></td><td colspan="3" class="small">rechte Seite separat</td></tr>`:""}`).join("")}</tbody></table><div class="row wrap" style="margin-top:10px"><button class="btn secondary" data-add-set="${idx}">+ Satz</button><input style="flex:1;min-width:130px" data-ex-note="${idx}" placeholder="Notiz / Technikhinweis" value="${esc(e.note||"")}"></div></div>`}
function wireSession(){$$("[data-set]").forEach(el=>{const [i,j]=el.dataset.set.split(",").map(Number);const key=el.dataset.key;const update=()=>{activeSession.exercises[i].sets[j][key]=el.type==="checkbox"?el.checked:el.value;saveSessionDraft()};el.onchange=update;el.oninput=update});$$("[data-add-set]").forEach(b=>b.onclick=()=>{activeSession.exercises[+b.dataset.addSet].sets.push({weight:"",reps:"",rir:2,type:"Arbeit",done:false});saveSessionDraft();renderSession()});$$("[data-remove-ex]").forEach(b=>b.onclick=()=>{activeSession.exercises.splice(+b.dataset.removeEx,1);saveSessionDraft();renderSession()});$$("[data-ex-note]").forEach(el=>el.oninput=()=>{activeSession.exercises[+el.dataset.exNote].note=el.value;saveSessionDraft()})}
function readProfileDraft(p){if(!p)return null;try{const saved=JSON.parse(localStorage.getItem(draftKey(p.id)));if(saved?.profileId===p.id&&saved.session)return saved.session;const legacy=JSON.parse(localStorage.getItem(DRAFT_KEY));if(legacy?.profileId===p.id)return legacy.session||legacy}catch(e){}return p.activeSession||null}
function saveSessionDraft(){if(!profile())return;profile().activeSession=activeSession;try{localStorage.setItem(draftKey(profile().id),JSON.stringify({profileId:profile().id,session:activeSession}));persistIndexedDB().catch(e=>console.warn("Entwurf konnte nicht in IndexedDB gespeichert werden",e))}catch(e){}}
function startWorkout(dayId){const pl=plan();if(!pl){toast("Bitte zuerst einen Trainingsplan aktivieren");return}if(activeSession){toast("Beende zuerst die aktive Einheit dieses Profils");return}const day=pl.days.find(d=>d.id===dayId)||pl.days[0];activeSession={id:uid(),profileId:profile().id,date:dateISO(),planId:pl.id,planName:pl.name,dayId:day.id,dayName:day.name,exercises:day.exercises.map(pe=>{const ex=state.exercises.find(x=>x.id===pe.exerciseId)||{name:"Übung",unilateral:false};return{exerciseId:pe.exerciseId,name:ex.name,muscle:ex.muscle||"",equipment:ex.equipment||"",equipmentId:ex.equipmentId||"",machineSettings:profile().equipment.find(q=>q.id===ex.equipmentId)?.settings.map(q=>({...q}))||[],unilateral:!!ex.unilateral,note:"",sets:Array.from({length:pe.sets||3},()=>({weight:"",reps:"",rir:pe.rir??2,type:"Arbeit",done:false}))}})};saveSessionDraft();go("training");setTab("session");renderSession()}
function finishWorkout(){if(!activeSession||activeSession.profileId!==profile().id)return;const duration=Math.max(1,Math.round((Date.now()-new Date(activeSession.date).getTime())/60000));const volume=activeSession.exercises.reduce((sum,e)=>sum+e.sets.filter(s=>s.done).reduce((a,s)=>a+(+s.weight||0)*(+s.reps||0)+(+s.weightR||0)*(+s.repsR||0),0),0);const saved=deepFreeze({...activeSession,endDate:dateISO(),duration,volume,exercises:activeSession.exercises.map(e=>({...e,sets:e.sets.map(s=>({...s}))}))});profile().sessions.push(saved);const completedProfileId=profile().id;profile().activeSession=null;activeSession=null;save();localStorage.removeItem(draftKey(completedProfileId));try{const legacyDraft=JSON.parse(localStorage.getItem(DRAFT_KEY));if(legacyDraft?.profileId===completedProfileId)localStorage.removeItem(DRAFT_KEY)}catch{};renderAll();go("history");toast("Training gespeichert")}
function setTab(tab){activeTab=tab;["plans","library","session"].forEach(t=>$("#tab-"+t).classList.toggle("hidden",t!==tab));$$("[data-tab]").forEach(b=>b.classList.toggle("btn",true));if(tab==="session")renderSession()}
function editPlan(id){const pl=profile().plans.find(p=>p.id===id);if(!pl)return;modal("Trainingsplan bearbeiten",`<div class="field"><label>Planname</label><input id="planNameEdit" value="${esc(pl.name)}"></div><div id="planDaysEdit">${pl.days.map((d,i)=>`<div class="item"><div class="row between"><b>${esc(d.name)}</b><button class="btn ghost" data-day-remove="${i}">Tag entfernen</button></div><div class="small">${d.exercises.map(x=>esc(state.exercises.find(e=>e.id===x.exerciseId)?.name||"Übung")).join(" · ")}</div><button class="btn secondary" data-day-edit="${i}" style="margin-top:8px">Übungen bearbeiten</button></div>`).join("")}</div><button class="btn secondary" id="addPlanDay" style="margin-top:10px">+ Trainingstag</button><button class="btn" id="savePlanEdit" style="margin-top:10px;width:100%">Änderungen speichern</button>`);$$("[data-day-remove]").forEach(b=>b.onclick=()=>{pl.days.splice(+b.dataset.dayRemove,1);editPlan(id)});$$("[data-day-edit]").forEach(b=>b.onclick=()=>editPlanDay(pl,+b.dataset.dayEdit));$("#addPlanDay").onclick=()=>{pl.days.push({id:uid(),name:"Neuer Tag",exercises:[]});editPlan(id)};$("#savePlanEdit").onclick=()=>{pl.name=$("#planNameEdit").value.trim()||pl.name;save();closeModal();renderAll();toast("Plan gespeichert")}}
function editPlanDay(pl,index){const d=pl.days[index];const draw=()=>{modal("Trainingstag bearbeiten",`<div class="field"><label>Name des Trainingstags</label><input id="dayName" value="${esc(d.name)}"></div><div class="small">Übungen und Zielvorgaben je Übung</div><div id="dayExercises">${d.exercises.map((x,i)=>`<div class="item"><div class="row between"><b>${esc(state.exercises.find(e=>e.id===x.exerciseId)?.name||"Übung")}</b><button class="btn ghost" data-day-ex-remove="${i}">Entfernen</button></div><div class="grid"><label class="field span-6">Sätze<input type="number" min="1" max="20" data-plan-dose="${i},sets" value="${x.sets||3}"></label><label class="field span-6">Wiederholungen<input data-plan-dose="${i},reps" value="${esc(x.reps||"8–12")}"></label><label class="field span-6">RIR<input type="number" min="0" max="10" data-plan-dose="${i},rir" value="${x.rir??2}"></label><label class="field span-6">Pause (Sek.)<input type="number" min="0" max="900" data-plan-dose="${i},rest" value="${x.rest||120}"></label></div></div>`).join("")}</div><div class="field"><label>Übung hinzufügen</label><select id="dayAddExercise">${state.exercises.map(e=>`<option value="${e.id}">${esc(e.name)} · ${esc(e.muscle)}</option>`).join("")}</select></div><button class="btn secondary" id="dayAddBtn">Hinzufügen</button><button class="btn" id="daySave" style="width:100%;margin-top:12px">Fertig</button>`);$("[data-plan-dose]").forEach(el=>el.oninput=()=>{const [i,key]=el.dataset.planDose.split(",");d.exercises[+i][key]=["sets","rir","rest"].includes(key)?Number(el.value):el.value});$("[data-day-ex-remove]").forEach(b=>b.onclick=()=>{d.exercises.splice(+b.dataset.dayExRemove,1);draw()});$("#dayAddBtn").onclick=()=>{d.exercises.push({id:uid(),exerciseId:$("#dayAddExercise").value,sets:3,reps:"8–12",rest:120,rir:2});draw()};$("#daySave").onclick=()=>{d.name=$("#dayName").value.trim()||d.name;save();editPlan(pl.id)}};draw()}
function editExercise(id){const e=state.exercises.find(x=>x.id===id);if(!e)return;modal("Übung bearbeiten",exerciseForm(e));wireExerciseForm(e)}
function exerciseForm(e={name:"",muscle:"Brust",equipment:"",unilateral:false,notes:""}){return `<div class="field"><label>Übungsname</label><input id="efName" value="${esc(e.name)}"></div><div class="field"><label>Muskelgruppe</label><select id="efMuscle">${muscles.slice(1).map(m=>`<option ${e.muscle===m?"selected":""}>${m}</option>`).join("")}</select></div><div class="field"><label>Gerät / Equipment</label><input id="efEquipment" list="machineModels" value="${esc(e.equipment)}" placeholder="Maschine, Kabel, Kurzhantel …"><datalist id="machineModels">${equipmentModels.map(x=>`<option value="${esc(x)}">`).join("")}</datalist></div><div class="field"><label>Mein Gerät (optional)</label><select id="efMachine"><option value="">Kein bestimmtes Gerät</option>${profile().equipment.map(q=>`<option value="${q.id}" ${e.equipmentId===q.id?"selected":""}>${esc(q.manufacturer)} · ${esc(q.model)}</option>`).join("")}</select></div><label class="row"><input type="checkbox" id="efUni" ${e.unilateral?"checked":""} style="width:auto"> Einseitige Übung (links/rechts getrennt)</label><div class="field"><label>Technikhinweise</label><textarea id="efNotes">${esc(e.notes||"")}</textarea></div><button class="btn" id="efSave" style="width:100%">Übung speichern</button>`}
function wireExerciseForm(existing){$("#efSave").onclick=()=>{const obj={id:existing?.id||uid(),name:$("#efName").value.trim(),muscle:$("#efMuscle").value,equipment:$("#efEquipment").value.trim(),equipmentId:$("#efMachine").value||"",unilateral:$("#efUni").checked,notes:$("#efNotes").value};if(!obj.name){toast("Bitte Übungsnamen eingeben");return}if(existing)Object.assign(existing,obj);else state.exercises.push(obj);save();closeModal();renderTraining();toast("Übung gespeichert")}}
function addExerciseModal(){modal("Neue Übung",exerciseForm());wireExerciseForm()}
function renderEquipment(){
 const p=profile(),all=p.equipment||[],q=($("#equipmentSearch")?.value||"").trim().toLowerCase(),categories=["Freihanteln","Maschinen","Kabelzüge","Körpergewicht","Sonstiges Zubehör"];
 const card=e=>`<div class="item equipment-card"><button class="equipment-main" data-eq-detail="${esc(e.id)}"><b>${esc(e.name||e.model||"Gerät")}</b><small>${esc([e.manufacturer,e.model].filter(Boolean).join(" · ")||e.type||e.category||"Allgemeines Trainingsgerät")}</small></button><button class="equipment-fav" data-eq-fav="${esc(e.id)}">${e.favorite?"★":"☆"}</button></div>`;
 $("#equipmentCategories").innerHTML=categories.map((c,i)=>`<button class="equipment-category" data-eq-category="${esc(c)}"><span>${["🏋️","⚙️","〰️","🤸","＋"][i]}</span><b>${esc(c)}</b><small>${all.filter(e=>e.category===c).length} Geräte</small></button>`).join("");
 const filtered=q?all.filter(e=>[e.name,e.manufacturer,e.model,e.type,e.category].join(" ").toLowerCase().includes(q)):all.filter(e=>e.category===equipmentCategory);
 if(q||equipmentCategory){$("#equipmentHome").classList.add("hidden");$("#equipmentCategoryView").classList.remove("hidden");$("#equipmentCategoryTitle").textContent=q?"Suchergebnisse":equipmentCategory;$("#equipmentList").innerHTML=filtered.map(card).join("")||'<p class="small muted">Keine passenden Geräte gefunden.</p>'}
 else{$("#equipmentHome").classList.remove("hidden");$("#equipmentCategoryView").classList.add("hidden");$("#equipmentFavorites").innerHTML=all.filter(e=>e.favorite).slice(0,8).map(card).join("")||'<p class="small muted">Noch keine Favoriten markiert.</p>';$("#equipmentRecent").innerHTML=all.filter(e=>e.lastUsedAt).sort((a,b)=>b.lastUsedAt-a.lastUsedAt).slice(0,6).map(card).join("")||'<p class="small muted">Zuletzt verwendete Geräte erscheinen hier.</p>'}
 $$("[data-eq-category]").forEach(b=>b.onclick=()=>{equipmentCategory=b.dataset.eqCategory;renderEquipment()});
 $$("[data-eq-detail]").forEach(b=>b.onclick=()=>equipmentDetail(b.dataset.eqDetail));
 $$("[data-eq-fav]").forEach(b=>b.onclick=()=>{const e=all.find(x=>x.id===b.dataset.eqFav);if(e){e.favorite=!e.favorite;save();renderEquipment()}});
 $("#equipmentBack").onclick=()=>{equipmentCategory="";$("#equipmentSearch").value="";renderEquipment()};
 $("#manufacturerTags").innerHTML=manufacturers.map(m=>`<button class="tag" data-maker="${esc(m)}">${esc(m)}</button>`).join("");
 $$("[data-maker]").forEach(b=>b.onclick=()=>{$("#equipmentSearch").value=b.dataset.maker;equipmentCategory="";renderEquipment()});
}
function equipmentDetail(id){const e=profile().equipment.find(x=>x.id===id);if(!e)return;modal(e.name||e.model||"Gerät",`<div class="detail-line"><span>Kategorie</span><b>${esc(e.category||"—")}</b></div><div class="detail-line"><span>Hersteller</span><b>${esc(e.manufacturer||"Nicht zugeordnet")}</b></div><div class="detail-line"><span>Modell</span><b>${esc(e.model||"Allgemeiner Gerätetyp")}</b></div><div class="detail-line"><span>Einstellungen</span><b>${(e.settings||[]).filter(x=>x.value).map(x=>esc(x.label)+": "+esc(x.value)).join(" · ")||"Nicht konfiguriert"}</b></div><div class="actions" style="margin-top:16px"><button class="btn" id="eqDetailEdit">Bearbeiten</button><button class="btn secondary" id="eqDetailFav">${e.favorite?"Favorit entfernen":"Als Favorit markieren"}</button><button class="btn danger" id="eqDetailDelete">Löschen</button></div>`);$("#eqDetailEdit").onclick=()=>editEquipment(id);$("#eqDetailFav").onclick=()=>{e.favorite=!e.favorite;save();closeModal();renderEquipment()};$("#eqDetailDelete").onclick=()=>{if(!confirm("Gerät entfernen? Historische Einheiten bleiben unverändert."))return;profile().equipment=profile().equipment.filter(x=>x.id!==id);profile().exercises.forEach(x=>{if(x.equipmentId===id)x.equipmentId="";});save();closeModal();renderEquipment()}}
function equipmentForm(e){const settings=e?.settings||[{label:"Sitzhöhe",value:""},{label:"Rückenlehne",value:""},{label:"Griffposition",value:""},{label:"Startposition",value:""},{label:"Bewegungsradius",value:""},{label:"Steckgewicht",value:""}];return `<div class="field"><label>Gerätebezeichnung</label><input id="eqName" value="${esc(e?.name||e?.model||"")}" placeholder="z. B. Brustpresse"></div><div class="field"><label>Kategorie</label><select id="eqCategory">${["Freihanteln","Maschinen","Kabelzüge","Körpergewicht","Sonstiges Zubehör"].map(c=>`<option ${e?.category===c?"selected":""}>${c}</option>`).join("")}</select></div><div class="field"><label>Hersteller</label><input id="eqManufacturer" list="makerList" value="${esc(e?.manufacturer||"")}" placeholder="Hersteller eingeben"><datalist id="makerList">${manufacturers.map(m=>`<option value="${esc(m)}">`).join("")}</datalist></div><div class="field"><label>Modell / Gerätename</label><input id="eqModel" value="${esc(e?.model||"")}" placeholder="z. B. Iso-Lateral Chest Press"></div><h3>Individuelle Geräteeinstellungen</h3><div id="eqSettings">${settings.map((s,i)=>settingRow(s,i)).join("")}</div><div class="actions"><button class="btn secondary" id="eqAddSetting">+ Einstellungsfeld</button></div><div class="field"><label>Notizen</label><textarea id="eqNotes">${esc(e?.notes||"")}</textarea></div><button class="btn" id="eqSave" style="width:100%">Gerät speichern</button>`}
function settingRow(s,i){return `<div class="row" style="margin:7px 0"><input placeholder="Einstellung" data-setting-label="${i}" value="${esc(s.label)}"><input placeholder="Wert" data-setting-value="${i}" value="${esc(s.value)}"><button class="btn ghost" data-setting-remove="${i}">✕</button></div>`}
function wireEquipmentForm(existing){$("#eqAddSetting").onclick=()=>{const ss=readSettings();ss.push({label:"",value:""});$("#eqSettings").innerHTML=ss.map(settingRow).join("");wireSettingRemove()};wireSettingRemove();$("#eqSave").onclick=()=>{const obj={...existing,id:existing?.id||uid(),name:$("#eqName").value.trim()||$("#eqModel").value.trim()||"Eigenes Gerät",category:$("#eqCategory").value,manufacturer:$("#eqManufacturer").value.trim(),model:$("#eqModel").value.trim(),type:existing?.type||"Individuelles Gerät",settings:readSettings(),notes:$("#eqNotes").value};if(existing)Object.assign(existing,obj);else profile().equipment.push(obj);save();closeModal();renderEquipment();toast("Gerät gespeichert")}}
function readSettings(){return $$("[data-setting-label]").map((el,i)=>({label:el.value.trim(),value:$(`[data-setting-value="${i}"]`)?.value.trim()||""})).filter(s=>s.label)}
function wireSettingRemove(){$$("[data-setting-remove]").forEach(b=>b.onclick=()=>{const ss=readSettings();ss.splice(+b.dataset.settingRemove,1);$("#eqSettings").innerHTML=ss.map(settingRow).join("");wireSettingRemove()})}
function addEquipment(){modal("Gerät hinzufügen",equipmentForm());wireEquipmentForm()}
function editEquipment(id){const e=profile().equipment.find(x=>x.id===id);if(e){modal("Geräteeinstellungen",equipmentForm(e));wireEquipmentForm(e)}}
function analyzedSets(sessions,fromDate){const rows=[];for(const session of sessions){if(fromDate&&new Date(session.date)<fromDate)continue;for(const exercise of session.exercises||[]){for(const set of exercise.sets||[]){if(set.done&&set.type!=="Aufwärmen"){const weight=Number(set.weight)||0,reps=Number(set.reps)||0;if(weight>0&&reps>0)rows.push({session,exercise,set,weight,reps,volume:weight*reps+((Number(set.weightR)||0)*(Number(set.repsR)||0))})}}}}return rows}
function renderAnalysis(){const p=profile(),sessions=p.sessions||[],cut=new Date();cut.setDate(cut.getDate()-30);const rows=analyzedSets(sessions,cut),volume=rows.reduce((a,r)=>a+r.volume,0);$("#analysisSessions").textContent=sessions.length;$("#analysisSets").textContent=rows.length;$("#analysisVolume").textContent=Math.round(volume).toLocaleString("de-AT");const musclesByName={};rows.forEach(r=>{const m=r.exercise.muscle||"Nicht zugeordnet",v=musclesByName[m]||{volume:0,sets:0};v.volume+=r.volume;v.sets++;musclesByName[m]=v});const entries=Object.entries(musclesByName).sort((a,b)=>b[1].volume-a[1].volume);$("#muscleVolume").innerHTML=entries.length?entries.map(([m,v])=>`<div class="statline"><span>${esc(m)}<span class="small"> · ${v.sets} ${v.sets===1?"Satz":"Sätze"}</span></span><b>${Math.round(v.volume).toLocaleString("de-AT")} kg</b></div>`).join(""):'<p class="small muted">Noch keine protokollierten Arbeitssätze in den letzten 30 Tagen.</p>';const records={};for(const r of analyzedSets(sessions,null)){const name=r.exercise.name||"Übung",estimate=r.weight*(1+r.reps/30),old=records[name];if(!old||estimate>old.value)records[name]={value:estimate,weight:r.weight,reps:r.reps,date:r.session.date}}const prs=Object.entries(records).sort((a,b)=>b[1].value-a[1].value).slice(0,8);$("#personalRecords").innerHTML=prs.length?prs.map(([name,r])=>`<div class="statline"><span>${esc(name)}<span class="small"> · ${r.weight} kg × ${r.reps}</span></span><b>${r.value.toFixed(1)} kg</b></div>`).join(""):'<p class="small muted">Rekorde erscheinen nach protokollierten Arbeitssätzen.</p>';const select=$("#analysisExercise"),previous=select.value,exerciseRows=analyzedSets(sessions,null),names=[...new Set(exerciseRows.map(r=>r.exercise.name).filter(Boolean))].sort((a,b)=>a.localeCompare(b,"de"));select.innerHTML=names.map(n=>`<option value="${esc(n)}">${esc(n)}</option>`).join("")||'<option value="">Keine Übungen</option>';if(names.includes(previous))select.value=previous;drawPerformanceChart(exerciseRows.filter(r=>r.exercise.name===select.value))}
function drawPremiumTrend(canvas,points){const ctx=canvas.getContext("2d"),w=canvas.width,h=canvas.height,left=42,right=14,top=14,bottom=30,plotW=w-left-right,plotH=h-top-bottom;ctx.clearRect(0,0,w,h);if(!points.length)return;const values=points.map(p=>p.value),lo=Math.min(...values),hi=Math.max(...values),pad=Math.max((hi-lo)*.2,Math.abs(hi)*.04,1),min=Math.max(0,lo-pad),max=hi+pad,range=max-min||1,x=i=>left+(points.length===1?plotW/2:i*plotW/(points.length-1)),y=v=>top+(max-v)/range*plotH;ctx.font="11px system-ui,sans-serif";ctx.textBaseline="middle";for(let i=0;i<4;i++){const yy=top+i*plotH/3,val=max-(range*i/3);ctx.strokeStyle="#ffffff12";ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(left,yy);ctx.lineTo(w-right,yy);ctx.stroke();ctx.fillStyle="#8f9398";ctx.textAlign="right";ctx.fillText(val.toFixed(0),left-8,yy)}const accent=getComputedStyle(document.documentElement).getPropertyValue("--accent").trim()||"#ffd21c";ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(x(i),y(p.value)):ctx.moveTo(x(i),y(p.value)));ctx.lineTo(x(points.length-1),top+plotH);ctx.lineTo(x(0),top+plotH);ctx.closePath();const gradient=ctx.createLinearGradient(0,top,0,top+plotH);gradient.addColorStop(0,"rgba(255,210,28,.27)");gradient.addColorStop(1,"rgba(255,210,28,.015)");ctx.fillStyle=gradient;ctx.fill();ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(x(i),y(p.value)):ctx.moveTo(x(i),y(p.value)));ctx.strokeStyle=accent;ctx.lineWidth=3;ctx.lineJoin="round";ctx.lineCap="round";ctx.shadowColor="rgba(255,210,28,.28)";ctx.shadowBlur=8;ctx.stroke();ctx.shadowBlur=0;points.forEach((p,i)=>{ctx.beginPath();ctx.arc(x(i),y(p.value),3.5,0,Math.PI*2);ctx.fillStyle=accent;ctx.fill();ctx.strokeStyle="#151719";ctx.lineWidth=2;ctx.stroke()});ctx.fillStyle="#85898d";ctx.font="10px system-ui,sans-serif";ctx.textAlign="center";const count=Math.min(points.length,5);for(let i=0;i<count;i++){const index=Math.round(i*(points.length-1)/Math.max(1,count-1)),d=new Date(points[index].date);if(!Number.isNaN(d.getTime()))ctx.fillText(d.toLocaleDateString("de-AT",{month:"short"}),x(index),h-11)}}function drawPerformanceChart(rows){const bySession=new Map();rows.forEach(r=>{const old=bySession.get(r.session.id);if(!old||r.weight>old.value)bySession.set(r.session.id,{value:r.weight,date:r.session.date})});drawPremiumTrend($("#performanceChart"),[...bySession.values()])}function renderHistory(){const p=profile(),ss=p.sessions.slice().sort((a,b)=>b.date.localeCompare(a.date));const volume=ss.reduce((a,s)=>a+(s.volume||0),0);$("#historyCount").textContent=ss.length;$("#historyVolume").textContent=Math.round(volume).toLocaleString("de-AT");$("#historyDays").textContent=new Set(ss.map(s=>s.date.slice(0,10))).size;$("#historyList").innerHTML=ss.map(s=>`<div class="item"><div class="row between"><div><div class="item-title">${esc(s.dayName)}</div><div class="small">${new Date(s.date).toLocaleString("de-AT")} · ${s.duration||0} min</div></div><b>${Math.round(s.volume||0).toLocaleString("de-AT")} kg</b></div><div class="small" style="margin-top:8px">${s.exercises.map(e=>esc(e.name||state.exercises.find(x=>x.id===e.exerciseId)?.name)).join(" · ")}</div><button class="btn ghost" data-session-view="${s.id}" style="margin-top:8px">Details</button></div>`).join("")||'<p class="small muted">Deine abgeschlossenen Einheiten erscheinen hier.</p>';$("[data-session-view]")&&$$("[data-session-view]").forEach(b=>b.onclick=()=>viewSession(b.dataset.sessionView));renderCalendar(ss);renderWeekBars(ss);drawWeightChart(p.weights||[])}
function renderCalendar(ss){const now=new Date(),y=now.getFullYear(),m=now.getMonth(),first=new Date(y,m,1).getDay(),days=new Date(y,m+1,0).getDate(),done=new Set(ss.map(s=>s.date.slice(0,10)));$("#calendarMonth").textContent=now.toLocaleDateString("de-AT",{month:"long",year:"numeric"});let html=["Mo","Di","Mi","Do","Fr","Sa","So"].map(x=>`<div class="day" style="background:transparent;color:#777">${x}</div>`).join("");const offset=(first+6)%7;for(let i=0;i<offset;i++)html+='<div class="day" style="background:transparent"></div>';for(let d=1;d<=days;d++){const key=`${y}-${String(m+1).padStart(2,"0")}-${String(d).padStart(2,"0")}`;html+=`<div class="day ${done.has(key)?"done":""} ${d===now.getDate()?"today":""}">${d}</div>`}$("#calendar").innerHTML=html}
function renderWeekBars(ss){const days=["So","Mo","Di","Mi","Do","Fr","Sa"],now=new Date();let html="";for(let i=6;i>=0;i--){const d=new Date(now);d.setDate(d.getDate()-i);const count=ss.filter(s=>new Date(s.date).toDateString()===d.toDateString()).length;html+=`<div class="row" style="margin:7px 0"><span class="small" style="width:26px">${days[d.getDay()]}</span><div class="bar" style="flex:1"><i style="width:${count?100:0}%"></i></div><span class="small" style="width:18px;text-align:right">${count}</span></div>`}$("#weekBars").innerHTML=html}
function drawWeightChart(weights){drawPremiumTrend($("#weightChart"),weights.slice(-12).map(x=>({value:+x.weight,date:x.date})))}function viewSession(id){const s=profile().sessions.find(x=>x.id===id);if(!s)return;modal("Training · "+esc(s.dayName),`<p class="small">${new Date(s.date).toLocaleString("de-AT")} · ${s.duration||0} Minuten · ${Math.round(s.volume||0)} kg Volumen</p>${s.exercises.map(e=>`<div class="item"><b>${esc(e.name||state.exercises.find(x=>x.id===e.exerciseId)?.name)}</b><div class="small">${e.sets.map((x,i)=>`S${i+1}: ${x.weight||0} kg × ${x.reps||0} · RIR ${x.rir??"—"}${x.done?" ✓":""}`).join("<br>")}</div>${e.note?`<p class="small">${esc(e.note)}</p>`:""}</div>`).join("")}`)}
function renderProfile(){const p=profile();$("#profileAvatar").textContent=p.name.slice(0,1).toUpperCase();$("#profileHeading").textContent=p.name;$("#profileSummary").innerHTML=[["Ziel",p.goal],["Niveau",p.level],["Körpergewicht",p.weight+" kg"],["Trainingsbeginn",p.startDate],["Aktiver Plan",plan()?.name||"Keiner"]].map(x=>`<div class="statline"><span class="small">${esc(x[0])}</span><b>${esc(x[1]??"—")}</b></div>`).join("");$("#weightInput").value=p.weight||"";$("#profilesList").innerHTML=state.profiles.map(x=>`<div class="item row between"><div><b>${esc(x.name)}</b><div class="small">${esc(x.goal)} · ${esc(x.level)}</div></div><div class="actions">${x.id===state.activeProfile?'<span class="tag">AKTIV</span>':`<button class="btn secondary" data-switch-profile="${x.id}">Wechseln</button>`}<button class="btn ghost" data-profile-edit="${x.id}">Bearbeiten</button></div></div>`).join("");$$("[data-switch-profile]").forEach(b=>b.onclick=()=>{profile().activeSession=activeSession;state.activeProfile=b.dataset.switchProfile;activeSession=readProfileDraft(profile());save();renderAll();toast("Profil gewechselt")});$$("[data-profile-edit]").forEach(b=>b.onclick=()=>editProfile(b.dataset.profileEdit));$("#accentColor").value=state.design.accent;$("#cardRadius").value=state.design.radius;$("#buttonStyle").value=state.design.button;$("#customTitle").value=state.design.title||""}
function profileForm(p){return `<div class="field"><label>Name</label><input id="pfName" value="${esc(p?.name||"")}"></div><div class="field"><label>Trainingsziel</label><select id="pfGoal">${["Muskelaufbau","Kraftaufbau","Fettabbau","Body Recomposition","Gesundheit & Fitness"].map(x=>`<option ${p?.goal===x?"selected":""}>${x}</option>`).join("")}</select></div><div class="field"><label>Trainingsniveau</label><select id="pfLevel">${["Einsteiger","Fortgeschritten","Sehr fortgeschritten"].map(x=>`<option ${p?.level===x?"selected":""}>${x}</option>`).join("")}</select></div><div class="field"><label>Körpergewicht (kg)</label><input type="number" step=".1" id="pfWeight" value="${esc(p?.weight||"")}"></div><div class="field"><label>Trainingsbeginn</label><input type="date" id="pfStart" value="${esc(p?.startDate||new Date().toISOString().slice(0,10))}"></div><button class="btn" id="pfSave" style="width:100%">Profil speichern</button>`}
function editProfile(id){const p=state.profiles.find(x=>x.id===id);modal("Profil bearbeiten",profileForm(p));$("#pfSave").onclick=()=>{p.name=$("#pfName").value.trim()||p.name;p.goal=$("#pfGoal").value;p.level=$("#pfLevel").value;p.weight=+$("#pfWeight").value||0;p.startDate=$("#pfStart").value;save();closeModal();renderAll()}}
function createProfile(){modal("Neues Profil",profileForm());$("#pfSave").onclick=()=>{const p={id:uid(),name:$("#pfName").value.trim()||"Neues Profil",goal:$("#pfGoal").value,level:$("#pfLevel").value,weight:+$("#pfWeight").value||0,startDate:$("#pfStart").value,activePlan:"",plans:[],sessions:[],equipment:baseEquipment.map(e=>({...e,settings:[]})),weights:[],exercises:baseExercises.map(e=>({...e})),activeSession:null};profile().activeSession=activeSession;state.profiles.push(p);state.activeProfile=p.id;activeSession=null;save();closeModal();renderAll();toast("Profil angelegt")}}
function exportBackup(){const blob=new Blob([JSON.stringify({format:"logbook-backup",backupVersion:1,exportedAt:dateISO(),data:state},null,2)],{type:"application/json"});const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="logbook-backup-"+new Date().toISOString().slice(0,10)+".json";a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast("Backup erstellt")}
function validateBackupData(data){if(!data||![1,2].includes(data.version)||!Array.isArray(data.profiles)||data.profiles.length<1||data.profiles.length>50)throw Error("Backup enthält keine gültige Profilstruktur");const ids=new Set();for(const p of data.profiles){if(!p||typeof p.id!=="string"||!p.id||ids.has(p.id))throw Error("Profil-IDs fehlen oder sind doppelt");ids.add(p.id);for(const key of ["plans","sessions","equipment","weights"]){if(p[key]!==undefined&&!Array.isArray(p[key]))throw Error(`Ungültige Daten in ${key}`)}for(const session of p.sessions||[]){if(!session||typeof session.id!=="string"||typeof session.date!=="string"||!Array.isArray(session.exercises))throw Error("Eine Trainingseinheit ist unvollständig");for(const ex of session.exercises){if(!ex||!Array.isArray(ex.sets))throw Error("Übungsdaten in der Historie sind ungültig")}}}if(data.exercises!==undefined&&!Array.isArray(data.exercises))throw Error("Übungsbibliothek ungültig");return true}function importBackup(file){const r=new FileReader();r.onload=()=>{try{const x=JSON.parse(r.result);if(x.format!=="logbook-backup"||x.backupVersion!==1)throw Error("Ungültiges oder nicht unterstütztes Backup");validateBackupData(x.data);const previous=state;if(!confirm("Backup importieren? Bestehende lokale Daten werden vollständig ersetzt."))return;state=normalizeState(x.data);try{save()}catch(e){state=previous;throw e}activeSession=profile().activeSession||null;renderAll();toast("Backup importiert")}catch(e){alert("Import fehlgeschlagen: "+e.message)}};r.readAsText(file)}
function bind(){ $$(".nav button").forEach(b=>b.onclick=()=>go(b.dataset.page));$("#analysisExercise").onchange=renderAnalysis;$$("[data-go]").forEach(b=>b.onclick=()=>go(b.dataset.go));$("#modalClose").onclick=closeModal;$("#modal").onclick=e=>{if(e.target.id==="modal")closeModal()};$("#profileQuick").onclick=()=>go("profile");$("#startNext").onclick=()=>startWorkout($("#nextWorkoutSelect").value);$$("[data-tab]").forEach(b=>b.onclick=()=>setTab(b.dataset.tab));$("#addTemplate").onclick=()=>{const name=$("#templateSelect").value;const pl=makePlan(name,templates[name]);profile().plans.push(pl);if(!profile().activePlan)profile().activePlan=pl.id;save();renderAll();toast("Vorlage hinzugefügt")};$("#newPlan").onclick=()=>{modal("Eigener Trainingsplan",`<div class="field"><label>Planname</label><input id="newPlanName" placeholder="z. B. Mein Hypertrophieplan"></div><button class="btn" id="createPlanSave">Plan erstellen</button>`);$("#createPlanSave").onclick=()=>{const n=$("#newPlanName").value.trim();if(!n)return;const p=makePlan(n,[["Training A",[]],["Training B",[]]]);profile().plans.push(p);profile().activePlan=p.id;save();closeModal();renderAll()}};$("#addExercise").onclick=addExerciseModal;$("#exerciseSearch").oninput=renderExerciseList;$("#addSessionExercise").onclick=()=>{modal("Übung zur Einheit hinzufügen",`<div class="field"><label>Übung</label><select id="sessionNewEx">${state.exercises.map(e=>`<option value="${e.id}">${esc(e.name)} · ${esc(e.muscle)}</option>`).join("")}</select></div><button class="btn" id="sessionNewAdd">Hinzufügen</button>`);$("#sessionNewAdd").onclick=()=>{const e=exByName(state.exercises.find(x=>x.id===$("#sessionNewEx").value)?.name);activeSession.exercises.push({exerciseId:e.id,name:e.name,note:"",sets:[{weight:"",reps:"",rir:2,type:"Arbeit",done:false}]});saveSessionDraft();closeModal();renderSession()}};$("#finishWorkout").onclick=()=>{if(confirm("Training abschließen und speichern?"))finishWorkout()};$("#addEquipment").onclick=addEquipment;$("#equipmentSearch").oninput=renderEquipment;$("#editProfile").onclick=()=>editProfile(profile().id);$("#manageProfiles").onclick=()=>go("profile");$("#createProfile").onclick=createProfile;$("#saveWeight").onclick=()=>{const w=+$("#weightInput").value;if(!w)return;profile().weight=w;profile().weights.push({date:dateISO(),weight:w});save();renderAll();toast("Gewicht gespeichert")};$("#editWeight").onclick=()=>{go("profile");$("#weightInput").focus()};$("#exportBackup").onclick=exportBackup;$("#importBackupBtn").onclick=()=>$("#importBackupFile").click();$("#importBackupFile").onchange=e=>e.target.files[0]&&importBackup(e.target.files[0]);$("#saveDesign").onclick=()=>{state.design={accent:$("#accentColor").value,radius:+$("#cardRadius").value,button:+$("#buttonStyle").value,title:$("#customTitle").value};save();applyDesign();toast("Darstellung gespeichert")}}
async function init(){await restoreIndexedDBIfNeeded();bind();activeSession=readProfileDraft(profile());if(activeSession&&confirm("Es gibt eine nicht abgeschlossene Trainingseinheit. Fortsetzen?")){saveSessionDraft()}else if(activeSession){activeSession=null;profile().activeSession=null;localStorage.removeItem(draftKey(profile().id));localStorage.removeItem(DRAFT_KEY);save()}renderAll();if("serviceWorker"in navigator&&location.protocol.startsWith("http"))navigator.serviceWorker.register("./sw.js").catch(()=>{});}
init();
